using YunXiaoJob.Application.DTOs.Responses;
using YunXiaoJob.Application.Interfaces;
using YunXiaoJob.Application.Interfaces.Repositories;
using YunXiaoJob.Domain.Enums;
namespace YunXiaoJob.Application.UseCases.Administration;
public class GetUsersUseCase { private readonly IUserRepository _users; public GetUsersUseCase(IUserRepository users) => _users = users; public async Task<IReadOnlyList<UserResponse>> ExecuteAsync(Guid uid, CancellationToken ct = default) { var admin = await _users.GetByIdAsync(uid, ct) ?? throw new UnauthorizedAccessException(); if (admin.PlatformRole != PlatformRole.Admin) throw new UnauthorizedAccessException(); return (await _users.GetAllAsync(ct)).Select(x => new UserResponse(x.Id, x.Email, x.FullName, x.PhoneNumber, x.PlatformRole, x.IsActive)).ToList(); } }
public class SetUserActiveUseCase { private readonly IUserRepository _users; private readonly IUnitOfWork _unit; public SetUserActiveUseCase(IUserRepository users, IUnitOfWork unit) { _users = users; _unit = unit; } public async Task<UserResponse> ExecuteAsync(Guid targetUserId, bool isActive, Guid uid, CancellationToken ct = default) { var admin = await _users.GetByIdAsync(uid, ct) ?? throw new UnauthorizedAccessException(); if (admin.PlatformRole != PlatformRole.Admin || targetUserId == uid) throw new UnauthorizedAccessException(); var user = await _users.GetByIdAsync(targetUserId, ct) ?? throw new KeyNotFoundException(); var now=DateTime.UtcNow; user.IsActive = isActive; user.UpdatedAtUtc = now; if(!isActive) await _users.RevokeRefreshTokensByUserIdAsync(user.Id, now, ct); await _unit.SaveChangesAsync(ct); return new UserResponse(user.Id,user.Email,user.FullName,user.PhoneNumber,user.PlatformRole,user.IsActive); } }
